begin;

set local search_path = pg_catalog, public;

-- Serviceaufgaben: recurring maintenance and control tasks. Templates hold the
-- recurrence rule; occurrences are generated by the service-tasks function.
-- All reads and writes go through that function (service role); the tables
-- have RLS enabled without client policies.

insert into public.feature_catalog (key, name, description, category, default_enabled)
values (
  'service.tasks',
  'Serviceaufgaben',
  'Wiederkehrende Wartungs- und Kontrollaufgaben mit Checkliste, Erinnerung und Nachweis.',
  'assets',
  true
)
on conflict (key) do update
set name = excluded.name,
    description = excluded.description,
    category = excluded.category,
    default_enabled = excluded.default_enabled;

insert into public.tenant_feature_flags (tenant_id, feature_key, enabled)
select tenant.id, 'service.tasks', true
from public.tenants as tenant
on conflict (tenant_id, feature_key) do nothing;

insert into public.permissions (code, description, is_sensitive)
values
  ('service_tasks.read', 'Serviceaufgaben ansehen', false),
  ('service_tasks.execute', 'Serviceaufgaben erledigen', false),
  ('service_tasks.manage', 'Serviceaufgaben anlegen und verwalten', true)
on conflict (code) do update
set description = excluded.description,
    is_sensitive = excluded.is_sensitive;

create or replace function public.service_task_default_permissions_for_role(
  p_name text,
  p_scope text
)
returns text[]
language sql
immutable
set search_path = pg_catalog
as $$
  select case
    when p_name in ('Tenant administrator', 'ICT Mitarbeiter') and p_scope = 'tenant'
      then array['service_tasks.read', 'service_tasks.execute', 'service_tasks.manage']
    when p_name = 'Support agent'
      then array['service_tasks.read', 'service_tasks.execute']
    else array[]::text[]
  end;
$$;

insert into public.role_permissions (role_id, permission_code)
select role.id, permission_code
from public.roles as role
cross join lateral unnest(
  public.service_task_default_permissions_for_role(role.name, role.scope::text)
) as permission_code
where role.active
on conflict (role_id, permission_code) do nothing;

create or replace function public.grant_default_service_task_permissions()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $$
begin
  if new.active then
    insert into public.role_permissions (role_id, permission_code)
    select new.id, permission_code
    from unnest(
      public.service_task_default_permissions_for_role(new.name, new.scope::text)
    ) as permission_code
    on conflict (role_id, permission_code) do nothing;
  end if;
  return new;
end;
$$;

revoke all on function public.grant_default_service_task_permissions()
  from public, anon, authenticated;

drop trigger if exists roles_grant_default_service_task_permissions on public.roles;
create trigger roles_grant_default_service_task_permissions
after insert or update of name, scope, is_system, active on public.roles
for each row execute function public.grant_default_service_task_permissions();

create table if not exists public.service_task_templates (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  title text not null check (char_length(btrim(title)) between 1 and 160),
  instructions text check (instructions is null or char_length(instructions) <= 4000),
  category text check (category is null or char_length(category) <= 60),
  priority text not null default 'normal'
    check (priority in ('low', 'normal', 'high', 'urgent')),
  assignee_id uuid references public.user_profiles(id) on delete set null,
  team_id uuid references public.teams(id) on delete set null,
  reference_label text
    check (reference_label is null or char_length(reference_label) <= 200),
  estimated_minutes integer
    check (estimated_minutes is null or estimated_minutes between 1 and 1440),
  recurrence jsonb not null check (jsonb_typeof(recurrence) = 'object'),
  starts_on date not null,
  ends_on date check (ends_on is null or ends_on >= starts_on),
  due_time time not null default '16:00',
  lead_days integer not null default 3 check (lead_days between 0 and 60),
  checklist jsonb not null default '[]'::jsonb
    check (jsonb_typeof(checklist) = 'array' and jsonb_array_length(checklist) <= 40),
  require_note boolean not null default false,
  remind boolean not null default true,
  escalate_after_days integer
    check (escalate_after_days is null or escalate_after_days between 1 and 30),
  active boolean not null default true,
  generated_until date,
  created_by uuid references public.user_profiles(id) on delete set null,
  updated_by uuid references public.user_profiles(id) on delete set null,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create index if not exists service_task_templates_tenant_idx
  on public.service_task_templates (tenant_id, active);

create table if not exists public.service_task_occurrences (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  template_id uuid not null references public.service_task_templates(id) on delete cascade,
  -- Date computed from the rule; stays fixed when a single due date is moved.
  scheduled_on date not null,
  due_on date not null,
  due_at timestamptz not null,
  visible_from date not null,
  status text not null default 'open'
    check (status in ('open', 'in_progress', 'done', 'skipped')),
  assignee_id uuid references public.user_profiles(id) on delete set null,
  checklist jsonb not null default '[]'::jsonb
    check (jsonb_typeof(checklist) = 'array'),
  note text check (note is null or char_length(note) <= 4000),
  skipped_reason text
    check (skipped_reason is null or char_length(skipped_reason) <= 500),
  started_at timestamptz,
  completed_at timestamptz,
  completed_by uuid references public.user_profiles(id) on delete set null,
  reminded_at timestamptz,
  escalated_at timestamptz,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  unique (template_id, scheduled_on)
);

create index if not exists service_task_occurrences_tenant_due_idx
  on public.service_task_occurrences (tenant_id, due_on);
create index if not exists service_task_occurrences_open_idx
  on public.service_task_occurrences (tenant_id, status, due_at)
  where status in ('open', 'in_progress');

create table if not exists public.service_task_events (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  occurrence_id uuid references public.service_task_occurrences(id) on delete cascade,
  template_id uuid references public.service_task_templates(id) on delete cascade,
  actor_id uuid references public.user_profiles(id) on delete set null,
  event text not null check (char_length(event) between 1 and 60),
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default timezone('utc', now())
);

create index if not exists service_task_events_occurrence_idx
  on public.service_task_events (occurrence_id, created_at);

alter table public.service_task_templates enable row level security;
alter table public.service_task_occurrences enable row level security;
alter table public.service_task_events enable row level security;
revoke all on public.service_task_templates from anon, authenticated;
revoke all on public.service_task_occurrences from anon, authenticated;
revoke all on public.service_task_events from anon, authenticated;

-- Push: reminders are ticket_notifications without a ticket, kind
-- "service_task.due" / "service_task.overdue", delivered to active members.
create or replace function public.push_notification_category(p_kind text)
returns text
language sql
immutable strict
set search_path = pg_catalog
as $function$
  select case
    when p_kind = 'ticket.assigned' then 'assigned'
    when p_kind = 'ticket.requester_reply' then 'requester_reply'
    when p_kind = 'ticket.support_reply' then 'support_reply'
    when p_kind = 'ticket.mention' then 'mention'
    when p_kind = 'ticket.resolved' then 'resolved'
    when p_kind = 'ticket.approval.requested' then 'approval'
    when p_kind = 'ticket.follow_up_due' then 'follow_up'
    when p_kind = 'ticket.escalation_opened' then 'escalation'
    when p_kind like 'ticket.sla.%' then 'sla'
    when p_kind = 'contract.deadline' then 'contract_deadline'
    when p_kind = 'inventory.low_stock' then 'inventory_low_stock'
    when p_kind like 'shop.order.%' then 'shop'
    when p_kind like 'service_task.%' then 'service_task'
    else null
  end;
$function$;

create or replace function public.push_enqueue_ticket_notification()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $function$
declare
  v_category text;
  v_categories text[];
begin
  v_category := public.push_notification_category(new.kind);
  if v_category is null then
    return new;
  end if;

  if new.kind = 'inventory.low_stock' then
    if not public.inventory_low_stock_delivery_authorized(new.tenant_id, new.user_id) then
      return new;
    end if;
  elsif not public.push_tenant_feature_enabled(new.tenant_id)
    or not exists (
      select 1
      from public.tenant_memberships membership
      where membership.tenant_id = new.tenant_id
        and membership.user_id = new.user_id
        and membership.status = 'active'
    )
    or not exists (
      select 1
      from public.push_devices device
      where device.tenant_id = new.tenant_id
        and device.user_id = new.user_id
        and device.enabled
    ) then
    return new;
  end if;

  select preference.enabled_categories
  into v_categories
  from public.push_preferences preference
  where preference.tenant_id = new.tenant_id
    and preference.user_id = new.user_id;
  v_categories := coalesce(v_categories, array[
    'assigned', 'requester_reply', 'support_reply', 'mention', 'resolved',
    'sla', 'escalation', 'approval', 'follow_up', 'contract_deadline', 'shop',
    'service_task'
  ]::text[]);
  -- Service task reminders are always offered, even for users whose stored
  -- preferences predate the category.
  if not v_category = any(v_categories) and v_category <> 'service_task' then
    return new;
  end if;

  insert into public.push_outbox (tenant_id, user_id, notification_id)
  values (new.tenant_id, new.user_id, new.id)
  on conflict (notification_id) do nothing;
  return new;
exception when others then
  return new;
end;
$function$;

create or replace function public.push_claim_outbox_v2(p_limit integer default 50)
returns table(outbox_id uuid, tenant_id uuid, user_id uuid, notification_id uuid, source_type text, ticket_id uuid, contract_id uuid, kind text, ticket_number text, subject text, delivery_mode text, devices jsonb)
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $function$
declare
  v_row record;
  v_kind text;
  v_ticket_id uuid;
  v_contract_id uuid;
  v_ticket_number text;
  v_subject text;
  v_ticket_available boolean;
  v_category text;
  v_mode text;
  v_global_enabled boolean;
  v_modes jsonb;
  v_enabled_categories text[];
  v_summary_hour smallint;
  v_timezone text;
  v_local_hour integer;
  v_quiet_enabled boolean;
  v_quiet_start smallint;
  v_quiet_end smallint;
  v_quiet boolean;
  v_devices jsonb;
begin
  if p_limit is null or p_limit < 1 or p_limit > 50 then
    raise exception 'invalid_push_claim_limit' using errcode = '22023';
  end if;

  update public.push_outbox
  set status = 'failed', last_error = 'attempt_limit'
  where status in ('pending', 'sending') and attempts >= 3;

  for v_row in
    select outbox.*
    from public.push_outbox outbox
    where outbox.attempts < 3
      and outbox.available_at <= timezone('utc', now())
      and (outbox.status = 'pending' or (
        outbox.status = 'sending'
        and outbox.claimed_at < timezone('utc', now()) - interval '5 minutes'
      ))
    order by outbox.available_at, outbox.created_at, outbox.id
    for update skip locked
    limit p_limit
  loop
    if not public.push_tenant_feature_enabled(v_row.tenant_id) then
      update public.push_outbox set status = 'skipped', last_error = 'feature_disabled'
      where id = v_row.id;
      continue;
    end if;
    if not exists (
      select 1
      from public.tenant_memberships membership
      where membership.tenant_id = v_row.tenant_id
        and membership.user_id = v_row.user_id
        and membership.status = 'active'
    ) then
      update public.push_outbox set status = 'skipped', last_error = 'membership_inactive'
      where id = v_row.id;
      continue;
    end if;

    v_kind := null;
    v_ticket_id := null;
    v_contract_id := null;
    v_ticket_number := null;
    v_subject := null;
    v_ticket_available := false;
    if v_row.source_type = 'ticket' then
      select
        notification.kind,
        notification.ticket_id,
        ticket.id is not null,
        ticket.ticket_number,
        case
          when feature.configuration ->> 'contentLevel' = 'subject'
            then ticket.subject
          else null
        end
      into
        v_kind,
        v_ticket_id,
        v_ticket_available,
        v_ticket_number,
        v_subject
      from public.ticket_notifications notification
      join public.tenant_feature_flags feature
        on feature.tenant_id = notification.tenant_id
        and feature.feature_key = 'notifications.push'
      left join public.tickets ticket
        on ticket.id = notification.ticket_id
        and ticket.tenant_id = notification.tenant_id
      where notification.id = v_row.notification_id
        and notification.tenant_id = v_row.tenant_id;
      if not found then
        update public.push_outbox set status = 'skipped', last_error = 'ticket_unavailable'
        where id = v_row.id;
        continue;
      end if;

      if v_ticket_id is null then
        -- Shop orders and service task reminders have no ticket; active
        -- membership was checked above.
        if v_kind like 'shop.order.%' or v_kind like 'service_task.%' then
          null;
        elsif v_kind <> 'inventory.low_stock'
          or not public.inventory_low_stock_delivery_authorized(
            v_row.tenant_id,
            v_row.user_id
          ) then
          update public.push_outbox set status = 'skipped', last_error = 'recipient_not_authorized'
          where id = v_row.id;
          continue;
        end if;
      elsif not v_ticket_available
        or not public.ticket_notification_recipient_authorized(
          v_row.tenant_id,
          v_ticket_id,
          v_row.user_id
        ) then
        update public.push_outbox set status = 'skipped', last_error = 'recipient_not_authorized'
        where id = v_row.id;
        continue;
      end if;
    else
      select event.contract_id, 'contract.deadline'::text
      into v_contract_id, v_kind
      from public.contract_deadline_push_events event
      where event.id = v_row.contract_event_id
        and event.tenant_id = v_row.tenant_id
        and event.recipient_user_id = v_row.user_id;
      if not found or not public.push_contract_delivery_authorized(
        v_row.tenant_id,
        v_row.user_id,
        v_contract_id
      ) then
        update public.push_outbox set status = 'skipped', last_error = 'recipient_not_authorized'
        where id = v_row.id;
        continue;
      end if;
    end if;

    v_category := public.push_notification_category(v_kind);
    if v_category is null then
      update public.push_outbox set status = 'skipped', last_error = 'unsupported_kind'
      where id = v_row.id;
      continue;
    end if;

    select preference.global_enabled, preference.category_modes, preference.enabled_categories,
           preference.summary_hour, preference.quiet_hours_enabled, preference.quiet_start,
           preference.quiet_end, preference.timezone
    into v_global_enabled, v_modes, v_enabled_categories, v_summary_hour,
         v_quiet_enabled, v_quiet_start, v_quiet_end, v_timezone
    from public.push_preferences preference
    where preference.tenant_id = v_row.tenant_id
      and preference.user_id = v_row.user_id;
    v_global_enabled := coalesce(v_global_enabled, true);
    v_modes := coalesce(v_modes, '{}'::jsonb);
    v_enabled_categories := coalesce(v_enabled_categories, array[
      'assigned', 'requester_reply', 'support_reply', 'mention', 'resolved',
      'sla', 'escalation', 'approval', 'follow_up', 'contract_deadline',
      'shop', 'service_task'
    ]::text[]);
    -- Older stored preferences do not know the category yet: deliver it.
    if v_category = 'service_task'
       and not 'service_task' = any(v_enabled_categories)
       and not (v_modes ? 'service_task') then
      v_enabled_categories := v_enabled_categories || 'service_task'::text;
    end if;
    v_summary_hour := coalesce(v_summary_hour, 8);
    v_quiet_enabled := coalesce(v_quiet_enabled, false);
    v_quiet_start := coalesce(v_quiet_start, 22);
    v_quiet_end := coalesce(v_quiet_end, 7);
    v_timezone := coalesce(v_timezone, 'Europe/Zurich');
    if not v_global_enabled then
      update public.push_outbox set status = 'skipped', last_error = 'global_disabled'
      where id = v_row.id;
      continue;
    end if;
    v_mode := public.push_delivery_mode(v_modes, v_enabled_categories, v_category);
    if v_mode = 'off' then
      update public.push_outbox set status = 'skipped', last_error = 'preference_disabled'
      where id = v_row.id;
      continue;
    end if;

    begin
      v_local_hour := extract(hour from timezone(v_timezone, now()))::integer;
    exception when others then
      v_timezone := 'Europe/Zurich';
      v_local_hour := extract(hour from timezone(v_timezone, now()))::integer;
    end;
    v_quiet := v_quiet_enabled and v_quiet_start <> v_quiet_end and case
      when v_quiet_start < v_quiet_end then v_local_hour >= v_quiet_start and v_local_hour < v_quiet_end
      else v_local_hour >= v_quiet_start or v_local_hour < v_quiet_end
    end;
    if v_quiet or not coalesce((public.push_work_state(v_row.tenant_id, v_row.user_id) ->> 'active')::boolean, false) then
      update public.push_outbox
      set status = 'pending', claimed_at = null, available_at = timezone('utc', now()) + interval '15 minutes',
          last_error = case when v_quiet then 'deferred_quiet_hours' else 'deferred_off_shift' end
      where id = v_row.id;
      continue;
    end if;
    if v_mode = 'summary' and v_local_hour <> v_summary_hour then
      update public.push_outbox
      set status = 'pending', claimed_at = null, available_at = timezone('utc', now()) + interval '15 minutes',
          last_error = 'deferred_summary'
      where id = v_row.id;
      continue;
    end if;

    select jsonb_agg(jsonb_build_object(
      'id', device.id, 'token', device.apns_token, 'environment', device.apns_environment
    ) order by device.created_at)
    into v_devices
    from public.push_devices device
    where device.tenant_id = v_row.tenant_id
      and device.user_id = v_row.user_id
      and device.enabled;
    if v_devices is null then
      update public.push_outbox set status = 'skipped', last_error = 'no_active_devices'
      where id = v_row.id;
      continue;
    end if;

    update public.push_outbox
    set status = 'sending', attempts = attempts + 1,
        claimed_at = timezone('utc', now()), last_error = null
    where id = v_row.id;
    outbox_id := v_row.id;
    tenant_id := v_row.tenant_id;
    user_id := v_row.user_id;
    notification_id := v_row.notification_id;
    source_type := v_row.source_type;
    ticket_id := v_ticket_id;
    contract_id := v_contract_id;
    kind := v_kind;
    ticket_number := v_ticket_number;
    subject := v_subject;
    delivery_mode := v_mode;
    devices := v_devices;
    return next;
  end loop;
end;
$function$;

-- Periodic wake-up of the service-tasks function (generation, reminders,
-- escalation). URL and shared secret live in a private, service-only table.
create schema if not exists service_task_private;
revoke all on schema service_task_private from public, anon, authenticated;

create table if not exists service_task_private.dispatch_config (
  singleton boolean primary key default true check (singleton),
  function_url text not null,
  dispatch_secret text not null check (char_length(dispatch_secret) >= 32)
);
revoke all on service_task_private.dispatch_config from public, anon, authenticated;

create or replace function public.service_task_wake()
returns void
language plpgsql
security definer
set search_path = pg_catalog, public, service_task_private, pg_temp
as $function$
declare
  v_url text;
  v_secret text;
begin
  if not exists (
    select 1 from public.service_task_templates template where template.active
  ) then
    return;
  end if;
  select config.function_url, config.dispatch_secret
  into v_url, v_secret
  from service_task_private.dispatch_config config
  where config.singleton;
  if v_url is null or v_secret is null
     or to_regprocedure('net.http_post(text,jsonb,jsonb,jsonb,integer)') is null then
    return;
  end if;
  execute 'select net.http_post($1, $2, $3, $4, $5)'
    using v_url,
          jsonb_build_object('type', 'cron'),
          '{}'::jsonb,
          jsonb_build_object(
            'Content-Type', 'application/json',
            'x-nextdesk-dispatch-secret', v_secret
          ),
          10000;
exception when others then
  return;
end;
$function$;

revoke all on function public.service_task_wake() from public, anon, authenticated;

commit;
